<script setup lang="ts">
import {ref,computed} from 'vue';import {useApp} from '../stores/app';import {coachAdvice} from '../core/logic';import Icon from '../components/Icon.vue';
const app=useApp(),energy=ref(3),soreness=ref(2),sleep=ref(8),message=ref(''),busy=ref(false);const advice=computed(()=>coachAdvice(app.completed,app.data.checkins.at(-1)));
async function save(){busy.value=true;try{await app.checkIn({energy:energy.value,soreness:soreness.value,sleep:sleep.value});message.value='Check-in saved. Your guidance has been updated.';}catch{message.value='Unable to save check-in.';}finally{busy.value=false;}}
</script>
<template><section class="page-heading"><div><div class="eyebrow">LISTEN TO YOUR BODY</div><h1>Training, with <span>perspective.</span></h1><p>A little reflection helps you decide what comes next.</p></div><span class="pill"><Icon name="ShieldCheck" :size="16"/>No external AI</span></section><div class="two-columns"><section class="card coach-feature"><span class="coach-orb"><Icon name="Sparkles" :size="36"/></span><span class="eyebrow">YOUR LOCAL COACH</span><h2>{{advice.title}}</h2><p>{{advice.body}}</p><div class="callout"><strong>Why this suggestion?</strong><p>{{advice.why}}</p></div><RouterLink to="/train" class="button primary">Explore your next session<Icon name="ArrowRight"/></RouterLink><p class="fine muted">An explainable rule-based assistant, not a language model or a medical professional. Recommendations never change your weights automatically.</p></section><section class="card"><div class="section-title"><h3>How are you feeling?</h3><span class="muted">TODAY</span></div><form class="checkin-form" @submit.prevent="save"><label>Energy <strong>{{energy}} / 5</strong><input v-model.number="energy" type="range" min="1" max="5" step="1"><span class="range-labels"><small>Running low</small><small>Ready to go</small></span></label><label>Muscle soreness <strong>{{soreness}} / 5</strong><input v-model.number="soreness" type="range" min="1" max="5" step="1"><span class="range-labels"><small>Feeling fresh</small><small>Very sore</small></span></label><label>Last night’s sleep (hours)<input v-model.number="sleep" type="number" min="0" max="24" step="0.5" required></label><button class="button primary full" :disabled="busy">Save today’s check-in<Icon name="Check"/></button></form><p role="status" class="lime-text">{{message}}</p><p class="fine muted">Check-ins are subjective. A low score is not a diagnosis.</p></section></div><div class="card callout"><strong>Pain is a reason to pause.</strong><p>Stop movements that hurt. Seek urgent help for chest pain, fainting, or severe symptoms. The coach cannot assess injuries or provide rehabilitation.</p></div></template>
